const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',shirt:'m8 3-5 3 3 5 2-1v11h8V10l2 1 3-5-5-3a4 4 0 0 1-8 0',replay:'M3 10a9 9 0 1 1 1 8 M3 4v6h6 M12 7v6l4 2',flag:'M5 22V3 M5 3c6-4 8 4 15 0v10c-7 4-9-4-15 0',ball:'m12 3 4 7-4 5-5-4 1-7 M3 10l4 1-1 7 M12 15l2 6 M16 10l5-2 M19 18l-4-3 M3 12a9 9 0 1 0 18 0 9 9 0 1 0-18 0',arrow:'M5 12h14 M13 6l6 6-6 6',play:'m8 5 11 7-11 7z',pause:'M8 5v14 M16 5v14',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',info:'M12 11v6 M12 7v.1 M3 12a9 9 0 1 0 18 0 9 9 0 1 0-18 0',spark:'m12 3 2.6 6.4L21 12l-6.4 2.6L12 21l-2.6-6.4L3 12l6.4-2.6z',check:'m5 12 4 4L19 6',close:'m6 6 12 12 M6 18 18 6',swap:'M3 7h17l-4-4 M21 17H4l4 4',search:'M11 3a8 8 0 1 0 0 16 8 8 0 1 0 0-16 M17 17l5 5',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',share:'M12 16V3 m-5 5 5-5 5 5 M5 12v9h14v-9',shield:'M12 2 3 6v6c0 6 9 10 9 10s9-4 9-10V6z M8 12l3 3 5-6',press:'M4 18V9h6 M20 18V9h-6 M8 5l4-3 4 3 M12 3v12',balanced:'M4 8h16 M4 16h16 M8 5v6 M16 13v6',trophy:'M8 3h8v8a4 4 0 0 1-8 0z M8 5H4v3a4 4 0 0 0 4 4 M16 5h4v3a4 4 0 0 1-4 4 M12 15v6 M8 21h8',volume:'M3 9h4l5-5v16l-5-5H3z M16 8a6 6 0 0 1 0 8',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 1 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',clock:'M3 12a9 9 0 1 0 18 0 9 9 0 1 0-18 0 M12 6v6l4 2'};
function icon(n,size=18){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.ball}"/></svg>`;}
const crest=(club,size='')=>`<span class="crest ${size}" style="--crest:${club.color}" aria-hidden="true">${esc(club.mark)}</span>`;
const btn=(label,action,classes='secondary',extra='',ico='')=>`<button class="btn ${classes}" data-action="${action}" ${extra}>${ico?icon(ico,15):''}${label}</button>`;
const qaMode=new URLSearchParams(location.search).get('qa')==='1';
try{await backupBeforeUpgrade(localStorage,qaMode);}catch{console.warn('Upgrade backup unavailable; existing saves are retained. Export saves from Settings.');}
const storeKey=qaMode?'touchline.qa.v2':'touchline.v1';
let saved={};try{saved=JSON.parse(localStorage.getItem(storeKey)||'{}');}catch{}
let ui={page:'managerial',lineup:defaultLineup(),formation:'4-3-3',preset:'balanced',club:0,match:null,original:null,branchMatch:null,selectedSlot:null,filter:'ALL',search:'',cursor:0,running:false,speed:1,career:null,careerFixture:null,motion:false,...saved};
ui.matchCentre=ui.match?.version&&ui.match.version!=='2.0.0'?false:(ui.matchCentre??!ui.match);ui.running=false;ui.page=['match','squad','explorer','career','challenges','europe','dynasty','managerial','player-career'].includes(ui.page)?ui.page:'match';ui.club=CLUBS[ui.club]?ui.club:0;if(validateLineup(ui.lineup,ui.formation))ui.lineup=defaultLineup(ui.formation in FORMATIONS?ui.formation:'4-3-3');if(!FORMATIONS[ui.formation])ui.formation='4-3-3';if(!PRESETS[ui.preset])ui.preset='balanced';
try{if(ui.match)ui.match=cleanImport(ui.match);if(ui.original)ui.original=cleanImport(ui.original);if(ui.branchMatch)ui.branchMatch=cleanImport(ui.branchMatch);}catch{ui.match=null;ui.original=null;ui.branchMatch=null;}
let restoringArchive=false;
let toastTimer=null,saveWarning=false,playback=null,transitionPose=null,matchView=null,flow=null,lastAnimationTime=null;
function compactSave(value){const result={...value};for(const key of ['match','original','branchMatch']){const m=value[key];if(!m||!isLive(m))continue;result[key]={...m,compact:true,frames:m.frames.map(f=>{const {events,rosters,visualPose,...rest}=f;return rest;})};}return result;}
let saveWorker=null,saveJob=0,saveTimer=null,lastPlaybackSave=0;
function persist(){
 if(!ui.running){saveJob++;clearTimeout(saveTimer);saveTimer=null;persistNow();return;}
 if(saveTimer)return;
 saveTimer=setTimeout(()=>{saveTimer=null;lastPlaybackSave=performance.now();
  try{if(!saveWorker){saveWorker=new Worker(new URL('./save-serializer.js',import.meta.url),{type:'module'});saveWorker.onmessage=({data})=>{if(data.id!==saveJob)return;const write=()=>{if(data.id!==saveJob)return;try{if(data.error)throw Error(data.error);localStorage.setItem(storeKey,data.json);document.body.dataset.autosave='worker';}catch{toast('Autosave unavailable. Pause the match to save again.');}};if(window.requestIdleCallback)requestIdleCallback(write,{timeout:1500});else setTimeout(write,0);};}saveWorker.postMessage({id:++saveJob,value:compactSave({...ui,running:false,selectedSlot:null,search:''})});}catch{document.body.dataset.autosave='deferred';}
 },Math.max(0,5000-(performance.now()-lastPlaybackSave)));
}
function persistNow(){try{localStorage.setItem(storeKey,JSON.stringify(compactSave({...ui,running:false,selectedSlot:null,search:''})));$('#save-status')?.replaceChildren(document.createTextNode('Saved on this device'));}catch{if(!saveWarning){saveWarning=true;toast('Device storage is full. Export your match to keep it.');}}}
function toast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3300);}
function current(){return ui.match?.state||createMatch({lineup:ui.lineup,formation:ui.formation,preset:ui.preset,club:ui.club,opponent:(ui.club+1)%8}).state;}
function stop(){captureLive();ui.running=false;}
function resetAnimation(){captureLive();playback=null;transitionPose=null;flow=null;}
function play(){if(!ui.match||ui.match.state.finished){startMatch();play();return;}captureLive();ui.running=!ui.running;render();persist();}
function tick(){if(!ui.match||ui.match.state.finished){stop();return;}if(!flow)flow=isLive(ui.match)?new LiveWorld(ui.match.state):new FlowWorld(ui.match.state);
 if(isLive(ui.match)){flow.plan(ui.match.state);playback={next:ui.match,elapsed:0,duration:2667};}
 else{const next=copy(ui.match);step(next);playback={next,elapsed:0,duration:4000};flow.plan(next.state);}}
function completeMinute(){if(!playback)return;
 if(isLive(ui.match)){commitWorld(ui.match,flow);}
 else{const pose=flow?.pose();if(pose){playback.next.state.visualPose=pose;playback.next.frames.at(-1).visualPose=pose;}ui.match=playback.next;}
 playback=null;const s=ui.match.state;ui.cursor=s.minute;persist();updateLive();if(s.finished){stop();commitCareer();render();}else if(s.minute===45){stop();render();toast('Half-time. Adjust your approach, then resume.');}}
function captureLive(){if(flow&&isLive(ui.match)){flow.writeState(ui.match.state);}}
function animationFrame(time){
 const dt=lastAnimationTime===null?0:Math.min(80,time-lastAnimationTime);lastAnimationTime=time;
 if(ui.running&&ui.page==='match'){if(!playback)tick();if(playback){const seconds=dt*ui.speed/1000;const steps=Math.max(1,Math.ceil(seconds/.025));for(let i=0;i<steps;i++)flow.update(seconds/steps);playback.elapsed+=dt*ui.speed;if(flow.ready(4))completeMinute();}}
 if(matchView&&(ui.running||!matchView.last||matchView.width!==matchView.canvas.clientWidth)){const source=ui.page==='explorer'?explorerSource():null;const s=source?(source.frames.find(f=>f.minute===Number(ui.cursor))||source.frames[0]):current();const reduced=ui.motion||window.matchMedia('(prefers-reduced-motion: reduce)').matches;const p=ui.page==='match'&&flow?flow.pose():s.visualPose||snapshot(s);matchView.draw(p,s,{moving:ui.running,reduced});if(ui.page==='match'&&playback){const clock=$('#live-time');if(clock)clock.textContent=(isLive(ui.match)?Math.min(90,Math.floor(flow.ticks/160)):playback.next.state.minute)+'′ · '+(playback.next.state.minute<=45?'FIRST HALF':'SECOND HALF');}const caption=$('#scene-caption');if(caption){const text=(playback?playback.next.state.minute:s.minute)+'′ · '+CLUBS[p.team===0?s.club:s.opponent].name+' · '+p.phase;if(caption.textContent!==text)caption.textContent=text;}}
 requestAnimationFrame(animationFrame);
}
function updateLive(){if(ui.page!=='match')return;const s=current();const set=(id,t)=>{const el=$(id);if(el)el.textContent=t;};set('#home-score',s.score[0]);set('#away-score',s.score[1]);set('#live-time',s.finished?'FULL-TIME':`${s.minute}′ · ${s.minute===45?'HALF-TIME':s.minute<45?'FIRST HALF':'SECOND HALF'}`);set('#fitness-value',fatigue(s)+'%');const f=$('#fitness-fill');if(f)f.style.width=fatigue(s)+'%';const progress=$('#match-progress');if(progress)progress.style.width=(s.minute/90*100)+'%';set('#minute-progress',s.minute+' / 90');const stats=$('#stats-panel');if(stats)stats.innerHTML=statsCard(s);const feed=$('#feed-panel');if(feed)feed.innerHTML=feedCard(s);const coach=$('#coach-panel');if(coach)coach.innerHTML=coachCard(s);const event=s.events.at(-1);if(event?.type==='goal'&&event.minute===s.minute){const el=$('#goal-flash');if(el){el.classList.remove('hidden');el.innerHTML=`<div class="big">GOAL!</div><small>${esc(event.scorer)} · ${s.minute}′</small>`;setTimeout(()=>el?.classList.add('hidden'),1600);}}}
function positions(s,i,away=false,squad=false){const slot=FORMATIONS[s.formation][i];if(squad)return [slot.x,slot.y];let x=slot.y*.85+7,y=slot.x*.82+9;if(away){x=100-x;y=100-y;}else{x+=(s.preset==='press'?4:s.preset==='protect'?-4:0);}if(s.minute>0){x+=Math.sin((s.minute+i*3)*.6)*2;y+=Math.cos((s.minute+i)*.7)*2;}return [Math.max(7,Math.min(93,x)),Math.max(9,Math.min(90,y))];}
function pitch(s,{squad=false,explore=false}={}){if(!squad)return `<div class="match-stage"><canvas id="match-canvas" aria-label="Animated football match. Home attacks right. Follow the event feed for text commentary." role="img"></canvas><div class="stage-top"><span class="broadcast-dot"></span><span>TOUCHLINE LIVE</span><span class="stage-direction">HOME ATTACKS →</span></div><div class="stage-bottom"><span id="scene-caption">${s.minute}′ · Ready</span><span>CONTINUOUS PLAY</span></div><div class="pitch-status hidden" id="goal-flash"></div></div>`;const lines=`<svg class="pitch-lines" viewBox="0 0 ${squad?'70 100':'100 65'}" preserveAspectRatio="none" aria-hidden="true">${squad?'<rect x="1" y="1" width="68" height="98" rx=".3"/><path d="M1 50h68 M20 1v15h30V1 M27 1v6h16V1 M20 99V84h30v15 M27 99v-6h16v6"/><circle cx="35" cy="50" r="10"/><circle cx="35" cy="50" r=".5" fill="currentColor"/>':'<rect x="1" y="1" width="98" height="63" rx=".3"/><path d="M50 1v63 M1 14h16v37H1 M1 24h6v17H1 M99 14H83v37h16 M99 24h-6v17h6"/><circle cx="50" cy="32.5" r="9"/><circle cx="50" cy="32.5" r=".5" fill="currentColor"/><path d="M17 24a10 10 0 0 1 0 17 M83 24a10 10 0 0 0 0 17"/>'}</svg>`;let players=s.lineup.map((id,i)=>{const pp=player(id),pos=positions(s,i,false,squad);return `<${squad?'button':'div'} class="footballer ${squad?'selectable':''} ${ui.selectedSlot===i&&squad?'selected':''}" ${squad?`data-action="slot" data-value="${i}" aria-label="Select ${esc(pp.name)}, ${pp.role}, slot ${i+1}"`:''} id="home-player-${i}" style="left:${pos[0]}%;top:${pos[1]}%"><div class="shirt">${i+1}</div><div class="player-label">${esc(pp.name.split(' ').at(-1))}</div></${squad?'button':'div'}>`;}).join('');if(!squad)players+=Array.from({length:11},(_,i)=>{const pos=positions(s,i,true);return `<div class="footballer away" id="away-player-${i}" style="left:${pos[0]}%;top:${pos[1]}%"><div class="shirt">${i+1}</div></div>`;}).join('');const notStarted=!ui.match&&!squad&&!explore;return `<div class="pitch ${squad?'vertical':''}" role="${squad?'group':'img'}" aria-label="${squad?'Your formation and selected players':'Schematic football pitch. The text event feed provides match details.'}">${lines}<span class="pitch-wordmark">TOUCHLINE</span>${players}${!squad?`<div id="live-ball" class="ball" style="left:${s.ball[0]}%;top:${s.ball[1]}%"></div>`:''}${notStarted?'<div class="pitch-status"><div class="big">THE STAGE IS SET.</div><small>Eleven players. Your decisions.</small></div>':''}<div class="pitch-status hidden" id="goal-flash"></div><div class="pitch-legend"><i></i>${squad?'YOUR STARTING XI':'SCHEMATIC MATCH VIEW'}</div></div>`;}
function scoreboard(s,explore=false){const home=CLUBS[s.club],away=CLUBS[s.opponent];return `<div class="scorebar"><div class="score-team"><div class="team-copy"><strong>${home.name}</strong><small>HOME</small></div>${crest(home)}</div><div class="score"><div class="score-numbers"><b id="home-score">${s.score[0]}</b><span>:</span><b id="away-score">${s.score[1]}</b></div><div class="score-time" id="live-time">${explore?`REPLAY · ${s.minute}′`:!ui.match?'FRIENDLY · READY TO PLAY':s.finished?'FULL-TIME':`${s.minute}′ · ${s.minute===45?'HALF-TIME':s.minute<45?'FIRST HALF':'SECOND HALF'}`}</div></div><div class="score-team away"><div class="team-copy"><strong>${away.name}</strong><small>AWAY</small></div>${crest(away)}</div></div>`;}
function statsCard(s){const rows=[['Possession',s.territory+'%',(100-s.territory)+'%',s.territory],['Shots',s.shots[0],s.shots[1],100*(s.shots[0]+1)/(s.shots[0]+s.shots[1]+2)],['Chance quality',s.xg[0].toFixed(2),s.xg[1].toFixed(2),100*(s.xg[0]+.1)/(s.xg[0]+s.xg[1]+.2)]];return `<div class="stats-title"><h3>Match pulse</h3>${icon('ball',14)}</div>${rows.map(([l,a,b,v])=>`<div class="stats-row"><span>${a}</span><span>${l}<div class="stat-track"><i style="width:${v}%"></i><i style="width:${100-v}%"></i></div></span><span>${b}</span></div>`).join('')}<div class="stat-foot">Chance quality is an authored game-model estimate.</div>`;}
function coachCard(s){const r=recommendation(s);return `<div class="eyebrow">YOUR ASSISTANT</div><div class="coach-icon">${icon('flag',22)}</div><h3>${esc(r.title)}</h3><p>${esc(r.text)}</p><div class="coach-action"><span>WHAT THE MATCH SAYS</span><b>${esc(r.evidence)}</b></div>${btn(r.label,r.action,'primary full',`${r.value?`data-value="${r.value}"`:''} ${r.out?`data-out="${r.out}" data-in="${r.in}"`:''}`)}<div class="stat-foot">Rules-based advice · actions change your actual match</div>`;}

function feedCard(s){const events=s.events.filter(e=>!['pass','tactic'].includes(e.type)).slice(-3).reverse();return `<div class="stats-title"><h3>From the touchline</h3><span class="badge">EVENT FEED</span></div>${events.length?events.map(e=>`<div class="feed-event"><span class="event-minute">${e.minute}′</span><span class="event-text">${esc(e.text)}</span></div>`).join(''):'<p class="feed-empty">Your next moment is coming.<br>Events from this match segment appear here.</p>'}`;}
function tactics(s,action='tactic'){return Object.entries(PRESETS).map(([key,t])=>`<button class="tactic-card ${s.preset===key?'active':''}" data-action="${action}" data-value="${key}" aria-pressed="${s.preset===key}"><span class="radio"></span><span class="tactic-title">${icon(key==='press'?'press':key==='protect'?'shield':'balanced',19)}${t.name}</span><p>${t.description}</p><div class="tactic-trade">${t.cost}</div></button>`).join('');}
function hero(title,description,actions='',eyebrow='YOUR SEASON STARTS HERE'){return `<section class="hero"><div><div class="season-label"><span></span>${eyebrow}</div><h1>${title}</h1><p>${description}</p></div><div class="hero-actions">${actions}</div></section>`;}
function matchPage(){if(ui.matchCentre)return renderMatchCentre();const s=current();const started=!!ui.match;return `${hero('YOUR CLUB. <em>YOUR CALL.</em>','Build your XI. Read the game. Rewrite the outcome.',btn('Your squad','nav','ghost','data-value="squad"','shirt')+btn(started?(s.finished?'New match':ui.running?'Pause match':'Resume match'):'Take the touchline',started&&s.finished?'new-match':'play','primary','','play'))}${started&&!isLive(ui.match)?`<div class="legacy-note"><span>This saved match uses the previous engine. Start a new match for continuous live football.</span>${btn('New live match','new-match','small secondary')}</div>`:''}<div class="grid-match"><section class="card"><div class="card-heading"><h2>Match centre <span style="color:#63765c;margin-left:8px">/ ${ui.careerFixture!==null?'CAREER FIXTURE':'QUICK MATCH'}</span></h2><span class="badge ${ui.running?'lime live':''}">${ui.running?'LIVE':s.finished?'FULL-TIME':started?'PAUSED':'PRE-MATCH'}</span></div>${s.finished?`<div class="finish-banner"><div><strong>${s.score[0]>s.score[1]?'A win for the club.':s.score[0]<s.score[1]?'Your next move starts here.':'All square at the whistle.'}</strong><span>Explore the moments. Try another approach.</span></div>${btn('Replay','nav','small primary','data-value="explorer"','replay')}</div>`:''}${scoreboard(s)}${presentationControls()}<div class="pitch-wrap">${pitch(s)}<div class="pitch-bottom"><div class="energy">${icon('shirt',12)} TEAM ENERGY <div class="energy-track"><i id="fitness-fill" style="width:${fatigue(s)}%"></i></div><span id="fitness-value">${fatigue(s)}%</span></div><span class="pitch-attribution">Original players · Authored simulation</span></div></div><div class="match-controls"><div class="control-left"><button class="icon-btn" data-action="play" aria-label="${ui.running?'Pause match':'Play match'}" ${s.finished?'disabled':''}>${icon(ui.running?'pause':'play',16)}</button><button class="speed" data-action="speed" aria-label="Change playback speed">${ui.speed}×</button><span class="progress"><i id="match-progress" style="width:${s.minute/90*100}%"></i></span><span id="minute-progress" class="minute-label">${s.minute} / 90</span></div><div class="control-right">${btn('Bench','bench','small secondary',!started||s.finished?'disabled':'','swap')}${btn('Full-time','finish','small ghost',!started||s.finished?'disabled':'','chevron')}</div></div></section><aside class="right-stack"><section class="card coach" id="coach-panel">${coachCard(s)}</section><section class="card stats-card" id="stats-panel">${statsCard(s)}</section><section class="card feed-card" id="feed-panel">${feedCard(s)}</section></aside></div><div class="section-heading"><h2>Your game plan</h2><span>${s.finished?'Choose your approach for the next match':'EVERY APPROACH HAS A TRADE-OFF'}</span></div><div class="tactics">${tactics(s)}</div>`;}
function squadPage(){const s=createMatch({lineup:ui.lineup,formation:ui.formation,preset:ui.preset,club:ui.club}).state;const q=teamAttributes(ui.lineup);return `${hero('ELEVEN PLAYERS. <em>ONE IDEA.</em>','Find the balance. Give every position a purpose.',btn('Auto-pick XI','auto-pick','secondary','','spark')+btn('To the pitch','nav','primary','data-value="match"','arrow'),'THE SQUAD BUILDER')}<div class="squad-layout"><section class="card"><div class="card-heading"><h2>${CLUBS[ui.club].name} · Starting XI</h2><span class="badge lime">${Math.round(q.rating)} OVR</span></div><div class="squad-toolbar"><select class="select" data-change="formation" aria-label="Select formation">${Object.keys(FORMATIONS).map(f=>`<option ${f===ui.formation?'selected':''}>${f}</option>`).join('')}</select><span class="budget">Draft budget <strong>${ui.lineup.reduce((n,id)=>n+player(id).cost,0)} / 420</strong></span></div><div class="pitch-wrap">${pitch(s,{squad:true})}</div><div class="squad-metrics"><div><span>ATTACK</span><strong>${Math.round(q.attack)}</strong></div><div><span>DEFENCE</span><strong>${Math.round(q.defense)}</strong></div><div><span>CONTROL</span><strong>${Math.round(q.control)}</strong></div></div></section><section class="card"><div class="pool-header"><div class="eyebrow">THE SCOUTING ROOM</div><h2 style="margin-top:9px">Find your next starter</h2><p>Pick a position on the pitch, then choose a player below.</p><div class="search-box">${icon('search',15)}<input id="player-search" placeholder="Search the player pool…" aria-label="Search player pool" value="${esc(ui.search)}"></div><div class="filters">${['ALL','GK','DEF','MID','FWD'].map(f=>`<button data-action="filter" data-value="${f}" class="${ui.filter===f?'active':''}">${f==='ALL'?'All players':f}</button>`).join('')}</div></div>${ui.selectedSlot!==null?`<div class="slot-hint">Replacing ${esc(player(ui.lineup[ui.selectedSlot]).name)} · ${FORMATIONS[ui.formation][ui.selectedSlot].role}</div>`:''}<div class="player-list" id="player-list">${playerRows()}</div></section></div><p class="match-annotation">All 48 player profiles are original game characters. Ratings and draft credits are authored game values. Squad edits apply to your next match; an existing match keeps its own lineup.</p>`;}
function playerRows(){return PLAYERS.filter(p=>(ui.filter==='ALL'||p.role===ui.filter)&&p.name.toLowerCase().includes(ui.search.toLowerCase())).sort((a,b)=>b.rating-a.rating).map(p=>`<button class="player-row" data-action="pick-player" data-value="${p.id}"><span class="player-rating">${p.rating}</span><span class="player-info"><strong>${esc(p.name)}</strong><small>${p.role} · ATT ${p.attack} · DEF ${p.defense} · STA ${p.stamina}</small></span><span class="player-price">${p.cost} cr</span>${ui.lineup.includes(p.id)?'<span class="selected-tag">IN XI</span>':`<span class="swap">${icon('swap',15)}</span>`}</button>`).join('')||'<div class="empty"><p>No players match this search.</p></div>';}
function explorerSource(){return ui.original||ui.match;}
function explorerPage(){const source=explorerSource();if(!source)return `${hero('EVERY MATCH <em>HAS A STORY.</em>','Play a match. Find the turning point. Try a different call.','','THE MATCH EXPLORER')}<div class="card empty"><div class="empty-symbol">${icon('replay',45)}</div><h2>Your first story is waiting.</h2><p>Finish a Quick Match or try a challenge to unlock its timeline and your alternative.</p>${btn('Start a match','nav','primary','data-value="match"','arrow')}</div>`;const frames=source.frames;const max=source.state.minute;const minute=Math.max(frames[0].minute,Math.min(max,Number(ui.cursor)||0));const s=frames.find(f=>f.minute===minute)||frames[0];const goals=source.state.events.filter(e=>e.type==='goal'||e.type==='tactic');const alt=ui.branchMatch;return `${hero('ONE MOMENT. <em>ANOTHER WAY.</em>','Rewind the match. Change your approach. Let the alternative play out.',btn('Export match','export','secondary','','download'),'THE MATCH EXPLORER')}<div class="explorer-layout"><div><section class="card"><div class="card-heading"><h2>Original match · ${CLUBS[s.club].short} vs ${CLUBS[s.opponent].short}</h2><span class="badge lime">${minute}′ SNAPSHOT</span></div>${scoreboard(s,true)}<div class="pitch-wrap">${pitch(s,{explore:true})}</div><div class="timeline-panel"><div class="timeline-label"><span>Move to a moment</span><span style="color:var(--lime)">${minute}′ / ${max}′</span></div><input id="timeline" type="range" min="${frames[0].minute}" max="${max}" step="1" value="${minute}" aria-label="Match timeline minute"><div class="timeline-events"><span>${frames[0].minute}′ START</span><span>${Math.round((frames[0].minute+max)/2)}′</span><span>${max}′ END</span></div><div class="timeline-ticks">${goals.map(e=>`<button data-action="jump" data-value="${e.minute}">${e.type==='goal'?'⚽':'↗'} ${e.minute}′ ${e.type==='goal'?esc(e.scorer):'Decision'}</button>`).join('')||'<span class="stat-foot">Scrub to any available minute to create an alternative.</span>'}</div></div></section><section class="card feed-card" style="margin-top:16px">${feedCard(s)}</section></div><aside><section class="card branch-options"><div class="eyebrow highlight">THE WHAT IF</div><h3>Make a different call.</h3><p>Start from minute ${minute}. Change the game plan and simulate the rest of this match.</p><label for="branch-preset" class="stat-foot" style="display:block;margin-top:16px">ALTERNATIVE APPROACH</label><select id="branch-preset" class="select">${Object.entries(PRESETS).map(([k,v])=>`<option value="${k}" ${k!==(s.preset)&&k==='press'?'selected':''}>${v.name}${k===s.preset?' · original':''}</option>`).join('')}</select>${btn('Rewrite from '+minute+'′','branch','primary full',minute>=90?'disabled':'','replay')}<p class="result-note">One simulated possibility, not a prediction. Your original match stays untouched.</p></section>${alt?`<section class="card comparison"><div class="eyebrow">TWO POSSIBLE STORIES</div><div class="compare-row"><span>Original result</span><b class="compare-score">${source.state.score.join(' : ')}</b></div><div class="compare-row"><span>Your alternative</span><b class="compare-score" style="color:var(--lime)">${alt.state.score.join(' : ')}</b></div><div class="compare-row"><span>Original shots</span><b>${source.state.shots[0]}</b></div><div class="compare-row"><span>Alternative shots</span><b>${alt.state.shots[0]}</b></div><p class="result-note">${PRESETS[alt.initial.preset]?.name||'Original'} → ${PRESETS[alt.state.preset].name} at ${alt.parent.minute}′.<br>Same saved random state; a different action can change the subsequent sequence. One run does not establish a better tactic.</p></section>`:`<section class="card stats-card" style="margin-top:16px">${statsCard(s)}</section>`}</aside></div><p class="match-annotation">Snapshots include lineup, fitness, tactics, event history and random-generator state. Match engine v${VERSION}. Career standings are unaffected by practice branches.</p>`;}
function newCareer(){return {club:ui.club,results:[],points:[0,0,0,0],played:[0,0,0,0],gf:[0,0,0,0],ga:[0,0,0,0],fixture:0,budget:120,objective:10};}
function careerTeams(){return [ui.career?.club??ui.club,...[1,2,3,4,5,6,7].filter(n=>n!==(ui.career?.club??ui.club)).slice(0,3)];}
function careerPage(){const c=ui.career,teams=careerTeams(),club=CLUBS[c?.club??ui.club];const schedule=[1,2,3,1,2,3];return `${hero('MORE THAN <em>NINETY MINUTES.</em>','A club to build. A season to remember. Every result stays with you.',c?btn('Start fresh','reset-career','ghost','','replay'):btn('Begin your career','start-career','primary','','flag'),'THE MANAGER’S OFFICE')}<div class="career-layout"><div><section class="card"><div class="club-banner">${crest(club,'large')}<div><div class="eyebrow">YOUR CLUB · MINI-SEASON</div><h2>${club.name}</h2><p>${club.motto}</p></div></div><div class="career-stats"><div><span>POINTS</span><b>${c?.points[0]||0}</b></div><div><span>PLAYED</span><b>${c?.fixture||0} / 6</b></div><div><span>REWARD CREDITS</span><b>${c?.budget??120}</b></div></div><div class="card-heading"><h2>The table</h2><span class="badge">4 CLUBS · 6 ROUNDS</span></div><table class="league-table"><thead><tr><th>#</th><th>CLUB</th><th>P</th><th>GD</th><th>PTS</th></tr></thead><tbody>${teams.map((id,i)=>({id,i,points:c?.points[i]||0,gd:(c?.gf[i]||0)-(c?.ga[i]||0)})).sort((a,b)=>b.points-a.points||b.gd-a.gd||((c?.gf[b.i]||0)-(c?.gf[a.i]||0))||a.i-b.i).map((t,pos)=>`<tr class="${t.i===0?'mine':''}"><td>${pos+1}</td><td>${CLUBS[t.id].name}</td><td>${c?.played[t.i]||0}</td><td>${t.gd>0?'+':''}${t.gd}</td><td><b>${t.points}</b></td></tr>`).join('')}</tbody></table></section><section class="card" style="margin-top:18px"><div class="card-heading"><h2>Your fixtures</h2><span class="badge">PRESEASON LEAGUE</span></div>${schedule.map((opp,i)=>{const r=c?.results[i];return `<div class="fixture"><span class="round">ROUND ${i+1}</span><strong>${CLUBS[teams[0]].short} <span>vs</span> ${CLUBS[teams[opp]].name}</strong>${r?`<b style="color:${r.score[0]>r.score[1]?'var(--lime)':'var(--text)'}">${r.score.join(' : ')}</b>`:`<span>${c?.fixture===i?'UP NEXT':'—'}</span>`}</div>`;}).join('')}</section></div><div><section class="card next-fixture"><div class="eyebrow highlight">${c?.fixture>=6?'SEASON COMPLETE':'YOUR NEXT CHAPTER'}</div><h3>${!c?'Step into the role.':c.fixture>=6?'A season in the books.':'Round '+(c.fixture+1)+': '+CLUBS[teams[schedule[c.fixture]]].name}</h3><p>${!c?'Take your squad through a compact six-match season. Commit real game results to the table and build your club record.':c.fixture>=6?`You earned ${c.points[0]} points. Replay your matches in Explorer or start a new season.`:'Prepare your XI, set the approach and play the next fixture. Results commit once; replay experiments never change the table.'}</p>${btn(!c?'Create your career':c.fixture>=6?'Start another season':'Play next fixture',!c?'start-career':c.fixture>=6?'reset-career':'career-match','primary full','','arrow')}</section><section class="card objective"><div class="eyebrow">THE BOARD’S OBJECTIVE</div><h3>Make your mark.</h3><p>Earn 10 points in six matches. A clear goal, with room for a few risks.</p><div class="progress"><i style="width:${Math.min(100,(c?.points[0]||0)*10)}%"></i></div><div class="stat-foot">${c?.points[0]||0} / 10 POINTS</div></section><section class="card objective"><div class="eyebrow">THIS FIRST BUILD</div><p>Fixtures, standings, save/resume and rewards work now. A transfer market, contracts and injury stories belong to the next career milestone. Reward credits are recorded but are not spendable yet.</p></section></div></div>`;}
function challengesPage(){return `${hero('THE CLOCK’S TICKING. <em>MAKE THE CALL.</em>','A difficult scoreline. A clear decision. A story waiting to change.','','THE SCENARIO ROOM')}<div class="history-choice">${[{minute:65,score:[0,1],title:'Chase the equaliser',tag:'THE COMEBACK',text:'Twenty-five minutes left. You’re a goal down. Can a higher press create the opening you need?'},{minute:70,score:[1,0],title:'Hold your nerve',tag:'PROTECT THE LEAD',text:'You’ve got the advantage. Stay on the front foot or close the middle? The choice is yours.'},{minute:45,score:[1,1],title:'Win the second half',tag:'THE RESET',text:'All square at the break. A fresh approach could change the rhythm of the next forty-five.'}].map((v,i)=>`<section class="card scenario"><div class="badge">ORIGINAL SCENARIO</div><div class="scenario-time">${v.minute}′</div><div class="eyebrow highlight">${v.tag}</div><h3>${v.title}</h3><p>${v.text}</p><div class="scenario-score">NORTHSTAR ${v.score[0]} : ${v.score[1]} HARBOUR</div>${btn('Take control','challenge','primary full',`data-value="${i}"`,'arrow')}</section>`).join('')}</div><p class="match-annotation">These are fictional scenarios authored for this game, not historical reconstructions. Real-match scenarios will be added only with suitable source coverage and data permissions.</p>`;}
function activeMode(){return ui.page==='europe'?'europe':ui.page==='player-career'?'player-career':'managerial';}
function managerLinks(){return careerDestinations.map(([page,label])=>`<button data-action="manager-destination" data-value="${page}">${({transfers:'Recruitment',season:'Season calendar',club:'Club overview'})[page]||label}</button>`).join('')+`<button data-action="nav" data-value="match" class="${ui.page==='match'?'active':''}">Match centre</button><details class="practice-nav"><summary>Original practice tools</summary>${practiceDestinations.map(([id,label])=>`<button class="${ui.page===id?'active':''}" data-action="nav" data-value="${id}">${label}</button>`).join('')}</details>`;}
function managerialPage(){const context=matchCentreCareer(),summary=managerResumeSummary(),resume=summary?{...summary,pending:['career','manager-connected'].includes(context.pending?.context)}:null;return renderCinematicHome(resume)+'<section class="cinema-desk" id="career-desk"><header><h2>Your career desk</h2><a href="#main">Back to the launcher ↑</a></header><div class="mgr-actions"><button class="btn secondary" data-action="training-ground">Training ground</button><button class="btn ghost" data-action="nav" data-value="match">Take the touchline</button></div>'+renderManagerHub(matchCentreCareer(),{welcome:false})+'</section>';}
function shell(){const resume=managerResumeSummary(),legacyClub=(ui.page==='match'&&!ui.matchCentre)||['squad','explorer','career','challenges'].includes(ui.page),sideClub=resume||(legacyClub?CLUBS[ui.club]:null)||{name:'Your next club',color:'#b6f36a',mark:'T'},clubAction=legacyClub&&!resume?'data-action="club"':resume?'data-action="manager-destination" data-value="office"':'data-action="nav" data-value="dynasty"';const titles={match:'Match centre',squad:'Squad builder',explorer:'Match explorer',career:'Practice league',challenges:'Challenges',europe:'Draft & Europe',dynasty:'Club manager career',managerial:'Managerial mode','player-career':'Player career'};return `<div class="app-shell"><aside class="sidebar"><button class="brand" data-action="nav" data-value="managerial" aria-label="Touchline home"><span class="brand-icon">T</span>touchline<span style="color:var(--lime)">.</span></button><div class="nav-label">THE DUGOUT</div><nav class="nav" aria-label="Main navigation">${[['managerial','shield','Managerial mode'],['europe','trophy','Draft & Europe'],['player-career','shirt','Player career']].map(([id,ic,label])=>`<button data-action="nav" data-value="${id}" class="${activeMode()===id?'active':''}" ${activeMode()===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></button>`).join('')}</nav><div class="mode-subnav" aria-label="Mode categories">${activeMode()==='managerial'?managerLinks():''}</div><div class="sidebar-club"><button class="switch-club" ${clubAction}><div class="club-row">${crest(sideClub,'small')}<div><div class="club-name">${esc(sideClub.name)}</div><div class="club-city">${resume?'YOUR CAREER':legacyClub?'ORIGINAL PRACTICE':'CHOOSE A CLUB'}</div></div></div>${icon('down',13)}</button><p>One badge. A thousand<br>possible stories.</p></div><div class="side-bottom"><button data-action="motion">${icon('settings',15)}${ui.motion?'Reduced motion on':'Match preferences'}</button><button data-action="about">${icon('info',15)}Settings & saves</button><small>FOOTBALL, ON YOUR TERMS.<br>TOUCHLINE © 2026 · v${APP_VERSION}</small></div></aside><div class="main-wrap"><header class="topbar"><div class="mobile-brand"><span class="brand-icon">T</span>touchline.</div><div class="breadcrumb">Your dugout ${icon('chevron',12)}<b>${titles[ui.page]}</b></div><div class="top-right"><span id="save-status"><i class="saved-dot"></i>Saved on this device</span><button class="mobile-settings icon-btn" data-action="about" aria-label="Settings & saves">${icon('settings',16)}</button><button class="avatar" ${clubAction} aria-label="${legacyClub&&!resume?'Practice club':'Open career club'}">${esc(sideClub.mark)}</button></div></header><main id="main" class="main" tabindex="-1"><p id="career-storage-status" class="stat-foot" role="status">${esc(largeSaveNotice())}</p>${legacyClub?`<section class="card practice-context"><span class="eyebrow">ORIGINAL PRACTICE AREA</span><p>${esc(CLUBS[ui.club].name)} · separate practice players and progress. ${resume?'Your career at '+esc(resume.name)+' is saved separately.':'Start a club career to use real teams and their squads.'}</p>${btn(resume?'Return to club career':'Choose a career club','manager-destination','secondary','data-value="office"')}</section>`:''}${largeSaveReadError()?'<section class="card mode-card"><h2>Recover your saved career</h2><p>The saved copy could not be loaded. It has been kept intact. Reload when device storage is available, or use Settings & saves to import a recovery archive.</p><button class="btn primary" data-action="about">Settings & saves</button><button class="btn secondary" data-action="save-career-previous">Download previous career snapshot</button></section>':({match:matchPage,squad:squadPage,explorer:explorerPage,career:renderPractice,managerial:managerialPage,'player-career':renderPlayerCareer,challenges:challengesPage,europe:renderEurope,dynasty:renderDynasty}[ui.page])()}<footer class="bottom-note"><span>THE BEAUTIFUL GAME. A DIFFERENT POSSIBILITY EVERY TIME.</span><button data-action="about">Authored simulation · v${APP_VERSION} ${icon('info',10)}</button></footer></main></div></div>`;}
function render(){document.body.dataset.page=ui.page;document.body.dataset.reduced=String(ui.motion);document.body.dataset.build=APP_VERSION;const focus=document.activeElement?.dataset;const restore=focus?.action?{action:focus.action,value:focus.value}:null;const previousView=matchView,previousCanvas=previousView?.canvas;$('#app').innerHTML=shell();const newCanvas=$('#match-canvas');if(previousCanvas&&newCanvas){newCanvas.replaceWith(previousCanvas);}else if(previousView){previousView.dispose?.();}document.body.classList.toggle('motion-off',ui.motion);matchView=$('#match-canvas')?(previousCanvas&&newCanvas?previousView:new MatchView($('#match-canvas'))):null;if(matchView)matchView.last=null;syncPresentationControls();syncCinematicHome();if(restore){const target=[...document.querySelectorAll('[data-action]')].find(el=>el.dataset.action===restore.action&&el.dataset.value===restore.value&&el.getClientRects().length);target?.focus({preventScroll:true});}}
function modal(content){stop();$('#modal').innerHTML=`<div class="modal-top"><span class="eyebrow highlight">TOUCHLINE</span><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close',16)}</button></div>${content}`;$('#modal').showModal();render();}
function closeModal(){$('#modal').close();}
function decisionPrompt(){const s=current();modal(`<h2>${s.score[0]<s.score[1]?'Change the story.':s.score[0]>s.score[1]?'How will you see this through?':'The next phase is yours.'}</h2><p>Minute ${s.minute}. ${CLUBS[s.club].name} ${s.score[0]} : ${s.score[1]} ${CLUBS[s.opponent].name}. Team energy ${fatigue(s)}%.</p><p>Choose an approach for the next phase. Each has a trade-off; none guarantees the outcome.</p><div class="decision-options">${Object.entries(PRESETS).map(([k,t])=>`<button class="tactic-card ${s.preset===k?'active':''}" data-action="decision" data-value="${k}"><span class="tactic-title">${t.name}${s.preset===k?' · current':''}</span><p>${t.description}</p><div class="tactic-trade">${t.cost}</div></button>`).join('')}</div>`);}

function confirmNew(callback){if(ui.match&&!ui.match.state.finished&&ui.match.state.minute>0){modal(`<h2>Start a new story?</h2><p>Your current match will be replaced. You can export it before starting again.</p><div class="modal-actions">${btn('Keep playing','close-modal','secondary')}${btn('Start new match','confirm-new','primary')}</div>`);pendingNew=callback;}else callback();}
let pendingNew=null;
function startMatch(options={}){ui.matchCentre=false;stop();playback=null;transitionPose=null;flow=null;ui.match=createMatch({lineup:ui.lineup,formation:ui.formation,preset:ui.preset,club:ui.club,opponent:(ui.club+1)%8,seed:20261018+Date.now()%100000,...options});ui.original=null;ui.branchMatch=null;ui.cursor=ui.match.state.minute;ui.page='match';persist();render();toast('Your team is ready. Take the touchline.');}
function beginAndPlay(options={}){startMatch(options);play();}
function applyTactic(key){if(ui.match&&!ui.match.state.finished){resetAnimation();applyAction(ui.match,{type:'preset',value:key});ui.preset=key;persist();const was=ui.running;render();ui.running=was;toast(PRESETS[key].name+' applied. '+PRESETS[key].cost+'.');}else{ui.preset=key;persist();render();}}
function pickPlayer(id){const pp=player(id);if(ui.lineup.includes(id)){ui.selectedSlot=ui.lineup.indexOf(id);ui.filter=pp.role;render();return;}let slot=ui.selectedSlot;if(slot===null||FORMATIONS[ui.formation][slot].role!==pp.role){slot=FORMATIONS[ui.formation].findIndex(s=>s.role===pp.role);if(slot<0){toast('This formation has no slot for that role.');return;}}const next=[...ui.lineup];next[slot]=id;const error=validateLineup(next,ui.formation);if(error){toast(error);return;}ui.lineup=next;ui.selectedSlot=slot;persist();render();toast(pp.name+' joins your XI.');}
function benchModal(){if(!ui.match||ui.match.state.finished)return;const s=current();modal(`<h2>Fresh legs. Fresh possibilities.</h2><p>${5-s.subs} substitutions remaining. Select a reserve with the same role.</p>${s.lineup.map(id=>{const available=s.bench.filter(b=>player(b).role===player(id).role);return `<div class="sub-line"><span>${esc(player(id).name)}<small>${player(id).role} · ${Math.round(s.fitness[id])}% energy</small></span>${available.length&&s.subs<5?`<select class="select" aria-label="Reserve for ${esc(player(id).name)}" id="sub-${id}">${available.map(b=>`<option value="${b}">${esc(player(b).name)}</option>`).join('')}</select><button class="btn small secondary" data-action="sub" data-value="${id}">Swap</button>`:'<span class="stat-foot">No eligible reserve</span>'}</div>`;}).join('')}`);}
function commitCareer(){if(ui.careerFixture===null||!ui.career||!ui.match?.state.finished)return;const c=ui.career,idx=ui.careerFixture;if(c.results[idx])return;const s=ui.match.state,opp=[1,2,3,1,2,3][idx];const add=(a,b,score)=>{c.played[a]++;c.played[b]++;c.gf[a]+=score[0];c.ga[a]+=score[1];c.gf[b]+=score[1];c.ga[b]+=score[0];if(score[0]>score[1])c.points[a]+=3;else if(score[0]<score[1])c.points[b]+=3;else{c.points[a]++;c.points[b]++;}};add(0,opp,s.score);const rest=[1,2,3].filter(n=>n!==opp);const other=[(idx*3+1)%4,(idx+2)%3];add(rest[0],rest[1],other);c.results[idx]={matchId:ui.match.id,score:[...s.score],opponent:opp};c.fixture=idx+1;c.budget+=s.score[0]>s.score[1]?30:s.score[0]===s.score[1]?15:5;ui.careerFixture=null;persist();toast('Fixture committed. Your league table is updated.');}
function branchNow(){const source=explorerSource();if(!source)return;stop();try{const alt=branch(source,Number(ui.cursor)||source.frames[0].minute,{type:'preset',value:$('#branch-preset').value});run(alt);if(!ui.original)ui.original=copy(source);ui.branchMatch=alt;persist();render();toast('Alternative complete. Your original match is unchanged.');}catch(e){toast(e.message);}}
function download(data,name,type='application/json'){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function exportMatch(){const m=explorerSource();if(!m){toast('Play a match first.');return;}download(JSON.stringify(m,null,2),'touchline-match-'+m.state.minute+'.json');}
function shareCard(){if(!ui.match)return;const s=ui.match.state;const canvas=document.createElement('canvas');canvas.width=1000;canvas.height=600;const c=canvas.getContext('2d');c.fillStyle='#101a12';c.fillRect(0,0,1000,600);c.fillStyle='#b6f36a';c.font='bold 28px sans-serif';c.fillText('touchline.',60,70);c.fillStyle='#eef4e6';c.font='bold 44px sans-serif';c.fillText(CLUBS[s.club].name,60,180);c.font='bold 100px sans-serif';c.fillText(s.score.join(' : '),60,310);c.font='32px sans-serif';c.fillText('vs '+CLUBS[s.opponent].name,60,380);c.fillStyle='#9caf91';c.font='22px sans-serif';c.fillText(PRESETS[s.preset].name+' · '+s.minute+' minutes',60,465);c.font='17px sans-serif';c.fillText('An authored football simulation. One possible story.',60,540);canvas.toBlob(blob=>{if(blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='touchline-result.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}});}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,v=el.dataset.value;if(qaMode)document.body.dataset.qaAction=a+':'+v;try{switch(a){case 'manager-destination':stop();openManagerDestination(v);break;case 'practice-original':stop();ui.matchCentre=false;ui.page='match';persist();render();break;case 'nav':stop();if(v==='match')ui.matchCentre=true;ui.page=v;window.scrollTo({top:0,behavior:'instant'});if(v==='explorer'&&ui.match){ui.cursor=Math.max(ui.match.frames[0].minute,Math.min(ui.match.state.minute-1,ui.match.state.minute>45?60:Math.max(0,ui.match.state.minute-5)));}persist();render();break;case 'play':play();break;case 'speed':ui.speed=ui.speed===1?2:ui.speed===2?4:1;persist();render();break;case 'finish':stop();captureLive();playback=null;transitionPose=null;flow=null;if(ui.match){run(ui.match);ui.cursor=ui.match.state.minute;commitCareer();persist();render();}break;case 'new-match':confirmNew(()=>{ui.careerFixture=null;startMatch();});break;case 'confirm-new':closeModal();pendingNew?.();pendingNew=null;break;case 'coach-sub':{if(!ui.match||ui.match.state.finished)break;const r=recommendation(ui.match.state);if(r.action!=='coach-sub'||r.out!==el.dataset.out||r.in!==el.dataset.in)break;resetAnimation();applyAction(ui.match,{type:'sub',out:r.out,in:r.in});persist();render();toast(player(r.in).name+' is on. Your substitution is recorded.');break;}case 'coach-build':resetAnimation();applyAction(ui.match,{type:'build',value:v});persist();render();break;case 'tactic':applyTactic(v);break;case 'decision':closeModal();applyTactic(v);if(!ui.running)play();break;case 'auto-pick':ui.lineup=defaultLineup(ui.formation);ui.selectedSlot=null;persist();render();toast('A balanced XI, picked for every role.');break;case 'slot':ui.selectedSlot=Number(v);ui.filter=FORMATIONS[ui.formation][ui.selectedSlot].role;render();toast('Selected '+player(ui.lineup[ui.selectedSlot]).name+'. Choose a '+ui.filter+' below.');break;case 'filter':ui.filter=v;render();break;case 'pick-player':pickPlayer(v);break;case 'bench':benchModal();break;case 'sub':resetAnimation();applyAction(ui.match,{type:'sub',out:v,in:$('#sub-'+v).value});persist();closeModal();render();toast('Substitution complete. Resume when you’re ready.');break;case 'jump':ui.cursor=Number(v);render();break;case 'branch':branchNow();break;case 'export':exportMatch();break;case 'share':shareCard();break;case 'start-career':ui.career=newCareer();persist();render();toast('Welcome to the club. Your first fixture awaits.');break;case 'reset-career':modal(`<h2>A new season?</h2><p>This replaces your current career standings and rewards. Your most recent match remains available in Explorer.</p><div class="modal-actions">${btn('Keep this season','close-modal','secondary')}${btn('Start fresh','confirm-career','primary')}</div>`);break;case 'confirm-career':closeModal();ui.career=newCareer();ui.careerFixture=null;persist();render();break;case 'career-match':confirmNew(()=>{const c=ui.career;if(!c||c.fixture>=6)return;ui.careerFixture=c.fixture;beginAndPlay({club:c.club,opponent:careerTeams()[[1,2,3,1,2,3][c.fixture]],seed:1000+c.fixture});});break;case 'challenge':confirmNew(()=>{ui.careerFixture=null;const scenario=[{minute:65,score:[0,1]},{minute:70,score:[1,0]},{minute:45,score:[1,1]}][Number(v)];beginAndPlay({...scenario,club:0,opponent:1,seed:9000+Number(v)});});break;case 'club':modal(`<h2>Choose your badge.</h2><p>Club selection changes Quick Match identity. An existing career keeps its club.</p><div class="club-picker">${CLUBS.map((c,i)=>`<button class="club-option ${ui.club===i?'active':''}" data-action="choose-club" data-value="${i}">${crest(c)}<strong>${c.name}</strong></button>`).join('')}</div>`);break;case 'choose-club':ui.club=Number(v);persist();closeModal();render();toast(CLUBS[ui.club].motto);break;case 'close-modal':closeModal();break;case 'motion':ui.motion=!ui.motion;persist();render();toast(ui.motion?'Reduced motion enabled.':'Standard motion enabled.');break;case 'save-export':stop();captureLive();persistNow();exportArchive(localStorage,qaMode).then(data=>{download(JSON.stringify(data),'touchline-saves-'+APP_VERSION+'.json');if(data.warning)toast(data.warning);else toast('All modes and available recorded replays exported.');}).catch(error=>toast(error.message));break;case 'save-career-previous':exportPreviousCareer(localStorage,qaMode).then(archive=>{download(JSON.stringify(archive),'touchline-previous-career.json');toast(archive.warning);}).catch(error=>toast(error.message));break;case 'save-recovery':latestBackup(qaMode?'qa':'normal').then(archive=>{if(!archive)throw Error('No recovery copy is stored yet.');download(JSON.stringify(archive),'touchline-recovery.json');toast('Recovery copy downloaded. Import it to restore the saved games.');}).catch(error=>toast(error.message));break;case 'save-import':$('#save-file')?.click();break;case 'about':modal(`<span class="eyebrow">SETTINGS & SAVES</span><h2>Football, on your terms.</h2><p><b>Build ${APP_VERSION}</b> · Physical engines ${VERSION} legacy · 2.1.0 for new Super League careers</p><p>Touchline is an original football management sandbox. Build a team, change tactics and explore a different outcome from a saved moment.</p><p>Quick Match uses original players and clubs. Drafts use historical football names with our own game ratings. English sandbox careers use dated real-player reference snapshots, pounds sterling and source-linked contract/valuation reports. Undisclosed terms and scouting projections are labelled. New Quick Matches use a continuous physical simulation. Goals require a ball crossing the goal line; ratings and execution errors are authored game values. Older saved matches retain their original model. Chance quality and tactical effects are game-model estimates, not real-world forecasts.</p><p>Includes English and Super League sandbox careers, create-a-club funding, transfers, contracts, historical drafts and real-club exhibitions. New live matches support playing with keyboard or touch controls as well as management. Original practice tools and saves remain in their own area. Live AI is disabled; coaching uses labelled rules-based advice. Imported player information is a dated reference snapshot; career events follow your save.</p>${offlinePanel()}<h3>Your saves</h3><p>Your current progress stays on this device. Export a portable archive, restore one, or recover a previous copy.</p><div class="save-controls">${btn('Export all saves','save-export','primary')}${btn('Import save archive','save-import','secondary')}${btn('Download recovery copy','save-recovery','ghost')}${btn('Download previous career snapshot','save-career-previous','ghost')}<input id="save-file" type="file" accept=".json,application/json" hidden></div><p class="stat-foot">Exports include all three modes and available physical replay records. Imports back up current saves before replacement. QA archives stay in the isolated test namespace.</p><div class="save-controls">${btn('Export last match','export','secondary','','download')}${btn('Download result card','share','primary',!ui.match?'disabled':'','share')}</div><h3>Match presentation</h3>${presentationControls()}<div class="presentation-controls"><label>Lighting<select data-presentation="lighting"><option value="auto">Club default</option><option value="day">Day</option><option value="night">Night</option></select></label><label>Stadium<select data-presentation="stadium"><option value="auto">Club default</option><option value="compact">Compact</option><option value="large">Large</option></select></label></div><p>Presentation preferences stay on this device. They do not change match results or recorded commands.</p><p>Engine ${VERSION} · Saves stay in your browser on this device.</p>`);break;}}catch(err){toast(err.message||'Something went wrong. Your last save is preserved.');}});
document.addEventListener('change',async e=>{if(e.target.id==='save-file'){const file=e.target.files[0];if(!file)return;try{if(file.size>40000000)throw Error('Save archive is too large (40 MB maximum).');const archive=validateArchive(JSON.parse(await file.text()));if(!confirm('Replace the saved games in all three modes with this archive? A recovery copy of your current saves will be stored first.'))return;if(document.querySelector('.matchday-busy'))throw Error('Stop the running season simulation before importing saves.');stop();saveJob++;clearTimeout(saveTimer);saveTimer=null;await importArchive(archive,localStorage,qaMode);restoringArchive=true;location.reload();}catch(error){toast(error.message);}return;}if(e.target.id==='timeline'){persist();render();return;}if(e.target.dataset.change==='formation'){ui.formation=e.target.value;ui.lineup=defaultLineup(ui.formation);ui.selectedSlot=null;persist();render();toast('Formation updated. Your XI has been rebalanced.');}});
document.addEventListener('input',e=>{if(e.target.id==='player-search'){ui.search=e.target.value;$('#player-list').innerHTML=playerRows();}if(e.target.id==='timeline'){ui.cursor=Number(e.target.value);if(matchView)matchView.last=null;const frame=(explorerSource()?.frames||[]).find(f=>f.minute===ui.cursor);if(frame){$('#home-score').textContent=frame.score[0];$('#away-score').textContent=frame.score[1];$('#live-time').textContent='REPLAY · '+frame.minute+'′';const canvas=$('#match-canvas');if(canvas&&!matchView)matchView=new MatchView(canvas);}}});
document.addEventListener('keydown',e=>{if(e.code==='Space'&&ui.page==='match'&&!ui.matchCentre&&!['INPUT','SELECT','BUTTON'].includes(e.target.tagName)&&!$('#modal').open){e.preventDefault();play();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&ui.running){stop();persist();render();}});
window.addEventListener('beforeunload',()=>{if(!restoringArchive){captureLive();persistNow();}});
installEurope({render,toast,navigate(page){stop();ui.page=page;persist();render();}});
installPractice({render,toast,context:()=>({club:ui.club,lineup:ui.lineup,formation:ui.formation})});
installPlayerCareer({render,toast});
installMatchCentre({career:matchCentreCareer,state:()=>ui.exhibition||{},save:state=>{ui.exhibition=state;persistNow();},render,toast});
installCinematicHome({toast});
render();startOpeningIntro();persist();requestAnimationFrame(animationFrame);

installOffline({canUpdate:()=>!ui.running&&canUpdateEurope()&&!document.querySelector('.live-fixture,.lab-player'),beforeUpdate:async()=>{captureLive();persistNow();await flushModeStorage();const archive=await exportArchive(localStorage,qaMode);await saveRecord((qaMode?'qa':'normal')+':backup:before-offline-switch:'+Date.now(),{backup:archive});}});

window.addEventListener('touchline-storage-status',()=>{const el=document.querySelector('#career-storage-status');if(el)el.textContent=largeSaveNotice();});
window.addEventListener('beforeunload',e=>{if(largeSaveUnsaved()){e.preventDefault();e.returnValue='';}});
